define('taoQtiItem/qtiCreator/model/interactions/GraphicGapMatchInteraction',['jquery', 'lodash', 'taoQtiItem/qtiCreator/model/mixin/editable', 'taoQtiItem/qtiCreator/model/mixin/editableInteraction', 'taoQtiItem/qtiItem/core/interactions/GraphicGapMatchInteraction', 'taoQtiItem/qtiCreator/model/choices/GapImg', 'taoQtiItem/qtiCreator/model/choices/AssociableHotspot'], function ($, _, editable, editableInteraction, Interaction, GapImg, AssociableHotspot) {
  "use strict";

  var methods = {};
  _.extend(methods, editable);
  _.extend(methods, editableInteraction);
  _.extend(methods, {
    getDefaultAttributes: function getDefaultAttributes() {
      return {
        maxAssociations: 0,
        minAssociations: 0
      };
    },
    afterCreate: function afterCreate() {
      var relatedItem = this.getRootElement();
      var isResponsive = relatedItem.data('responsive');
      this.addClass('qti-choices-bottom');
      if (isResponsive === true) {
        this.addClass('responsive');
      }
      this.createResponse({
        baseType: 'directedPair',
        cardinality: 'multiple'
      });
    },
    createGapImg: function createGapImg(object, label) {
      var gapImg = new GapImg();
      gapImg.object.attributes = object;
      if (label) {
        gapImg.attr('objectLabel', label);
      }
      if (!this.gapImgs) {
        this.gapImgs = [];
      }
      this.addGapImg(gapImg);
      gapImg.buildIdentifier('gapimg');
      if (this.getRenderer()) {
        gapImg.setRenderer(this.getRenderer());
      }
      $(document).trigger('choiceCreated.qti-widget', {
        'choice': gapImg,
        'interaction': this
      });
      return gapImg;
    },
    createChoice: function createChoice(attr) {
      var choice = new AssociableHotspot('', attr);
      this.addChoice(choice);
      choice.buildIdentifier('associablehotspot');
      if (this.getRenderer()) {
        choice.setRenderer(this.getRenderer());
      }
      $(document).trigger('choiceCreated.qti-widget', {
        'choice': choice,
        'interaction': this
      });
      return choice;
    }
  });
  return Interaction.extend(methods);
});
