define('taoQtiItem/qtiCreator/widgets/helpers/featureFlags',['context', 'services/features'], function (context, features) {
  'use strict';

  var MULTI_FIELD_SCORING_FLAG = 'FEATURE_FLAG_MULTI_FIELD_SCORING';
  var MULTI_FIELD_SCORING_VISIBILITY = 'taoQtiItem/creator/interaction/textEntry/property/multiFieldScoring';
  return {
    MULTI_FIELD_SCORING_FLAG,
    MULTI_FIELD_SCORING_VISIBILITY,
    isCompactAppearanceAvailable: function isCompactAppearanceAvailable() {
      return features.isVisible('taoQtiItem/creator/interaction/media/property/compactAppearance');
    },
    isMultiFieldScoringAvailable: function isMultiFieldScoringAvailable() {
      if (context.featureFlags && context.featureFlags[MULTI_FIELD_SCORING_FLAG] === true) {
        return true;
      }
      return features.isVisible(MULTI_FIELD_SCORING_VISIBILITY, false);
    }
  };
});
