define('taoQtiItem/qtiCreator/widgets/helpers/validators',['ui/validator/validators', 'lodash', 'i18n', 'taoQtiItem/qtiItem/core/Element', 'taoQtiItem/qtiCreator/model/helper/invalidator', 'taoQtiItem/qtiCreator/widgets/helpers/qtiResponseIdentifier'], function (validators, _, __, Element, invalidator, qtiResponseIdentifier) {
  'use strict';

  var _qtiIdPattern = qtiResponseIdentifier.pattern;
  var typeToMessage = {
    item: __('Invalid identifier'),
    response: __('Invalid response identifier'),
    outcome: __('Invalid Outcome Declaration'),
    lexicalGroup: __('Invalid Lexical Group Identifier')
  };
  var invalidIdentifier = qtiResponseIdentifier.invalidQtiIdMessage;
  var validateIdentifier = (value, callback, options, type) => {
    if (typeof callback === 'function') {
      var valid = _qtiIdPattern.test(value);
      if (options && options.serial) {
        var element = Element.getElementBySerial(options.serial);
        if (valid) {
          invalidator.valid(element, 'invalidIdentifier');
        } else {
          invalidator.invalid(element, 'invalidIdentifier', typeToMessage[type]);
        }
      }
      callback(valid);
    }
  };
  var qtiValidators = [{
    name: 'qtiResponseIdentifier',
    message: "<b>".concat(typeToMessage.item, "</b></br>").concat(invalidIdentifier),
    validate: function validate(value, callback, options) {
      validateIdentifier(value, callback, options, 'item');
    }
  }, {
    name: 'qtiResponseIdentifier',
    message: "<b>".concat(typeToMessage.response, "</b></br>").concat(invalidIdentifier),
    validate: function validate(value, callback, options) {
      validateIdentifier(value, callback, options, 'response');
    }
  }, {
    name: 'qtiOutcomeIdentifier',
    message: "<b>".concat(typeToMessage.outcome, "</b></br>").concat(invalidIdentifier),
    validate: function validate(value, callback, options) {
      validateIdentifier(value, callback, options, 'outcome');
    }
  }, {
    name: 'qtiLexicalGroupIdentifier',
    message: "<b>".concat(typeToMessage.lexicalGroup, "</b></br>").concat(invalidIdentifier),
    validate: function validate(value, callback, options) {
      validateIdentifier(value, callback, options, 'lexicalGroup');
    }
  }, {
    name: 'availableIdentifier',
    message: __('This identifier is already used by another variable.'),
    validate: function validate(value, callback, options) {
      if (options.serial) {
        var element = Element.getElementBySerial(options.serial);
        if (element && typeof callback === 'function') {
          var ids = element.getRootElement().getUsedIdentifiers();
          var available = !ids[value] || ids[value].serial === element.serial;
          callback(available);
        }
      } else {
        throw new Error('missing required option "serial"');
      }
    }
  }, {
    name: 'availableVariableIdentifier',
    message: __('identifier already taken'),
    validate: function validate(value, callback, options) {
      if (options.serial) {
        var element = Element.getElementBySerial(options.serial);
        if (element && typeof callback === 'function') {
          var ids = element.getRootElement().getUsedIdentifiers();
          var available = !ids[value] || ids[value].serial === element.serial || !ids[value].is('variableDeclaration');
          callback(available);
        }
      } else {
        throw new Error('missing required option "serial"');
      }
    }
  }, {
    name: 'isValidUrl',
    message: __('Invalid URL'),
    validate: function validate(value, callback) {
      if (value) {
        try {
          callback(new URL(value));
        } catch (error) {
          callback(false);
        }
      } else {
        callback(true);
      }
    }
  }];
  _.forEach(qtiValidators, function (rule) {
    validators.register(rule.name, rule);
  });
  return validators;
});
